# Rebuild collages with 56-px corners, mirror-tiled 2x2 per quadrant (no upscaling, fewer bird fragments)
def collage2(a, s=56):
    def tile(c):
        top = np.concatenate([c, c[:, ::-1]], 1)
        return np.concatenate([top, top[::-1]], 0)      # 112x112, mirror-tiled
    tl = tile(a[:s,:s]); tr = tile(a[:s,-s:][:, ::-1])[:, ::-1]
    bl = tile(a[-s:,:s][::-1])[::-1]; br = tile(a[-s:,-s:][::-1, ::-1])[::-1, ::-1]
    return np.concatenate([np.concatenate([tl,tr],1), np.concatenate([bl,br],1)],0)
